import humanize, datetime as dt
from decimal import Decimal
from fractions import Fraction
for v in [Decimal(-3661), Fraction(-3661), -3661, dt.timedelta(seconds=-0.1)]:
    try: print(repr(v), repr(humanize.precisedelta(v)))
    except Exception as e: print(repr(v), "ERR", e)
print(repr(humanize.precisedelta(-30, minimum_unit="minutes", format="%0.0f")))
print(repr(humanize.precisedelta(-30, minimum_unit="hours", format="%0.2f")))
try:
    import numpy as np; print(repr(humanize.precisedelta(np.int64(-3661))))
except ImportError: print("no numpy")
EOF

P=/home/yogi/.workbench-demo/t-01M4RZHVGFWY1FXM7RNXWAVNQA/venv/bin/python; $P -m pytest -q -p no:cacheprovider 2>&1 | tail -3; grep -n "line-length\|ruff\|doctest" pyproject.toml tox.ini .pre-commit-config.yaml 2>/dev/null; awk 'length>88{print FILENAME": "FNR": "length}' src/humanize/time.py tests/test_time.py; $P -m ruff --version 2>&1; $P -m ruff check src tests 2>&1|tail -5; $P -m ruff format --check src tests 2>&1 | tail -3
$P -c "
import humanize, datetime as dt
for v in [-0.3, dt.timedelta(microseconds=-1), dt.timedelta(days=-999999999), -1e-9]:
  try: print(repr(v), repr(humanize.precisedelta(v)), repr(humanize.precisedelta(-v if not isinstance(v,dt.timedelta) else abs(v))))
  except Exception as e: print(v, 'ERR', e)
print(humanize.precisedelta(dt.datetime.now()-dt.timedelta(hours=1)))
print(humanize.precisedelta(dt.timedelta(seconds=-3661), minimum_unit='hours'))
"

